from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/schemas/backtest.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom app.schemas.common import APIModel\n\n\nclass BacktestRequest(APIModel):\n    dataset_id: str\n    model_version: str = "champion"\n    minimum_net_edge: float = Field(default=0.03, ge=-1, le=1)\n    fee_multiplier: float = Field(default=0.07, ge=0, le=1)\n    slippage_per_contract: float = Field(default=0.01, ge=0, le=1)\n    uncertainty_buffer: float = Field(default=0.01, ge=0, le=1)\n    contracts_per_trade: int = Field(default=1, ge=1, le=100000)\n    maximum_total_exposure: float = Field(default=1000.0, gt=0)\n\n\nclass BacktestRunRead(APIModel):\n    id: str\n    status: str\n    dataset_id: str\n    model_version_id: str\n    configuration: dict[str, Any]\n    metrics: dict[str, Any]\n    trades: list[dict[str, Any]]\n    error_message: str | None\n    started_at: datetime | None\n    completed_at: datetime | None\n    created_at: datetime\n')
write('app/schemas/common.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import BaseModel, ConfigDict, Field\n\n\nclass APIModel(BaseModel):\n    model_config = ConfigDict(from_attributes=True, populate_by_name=True)\n\n\nclass HealthResponse(APIModel):\n    status: str\n    service: str\n    environment: str\n    timestamp: datetime\n    version: str\n\n\nclass ErrorDetail(APIModel):\n    code: str\n    message: str\n    details: dict[str, Any] | None = None\n\n\nclass Pagination(APIModel):\n    limit: int = Field(default=50, ge=1, le=500)\n    offset: int = Field(default=0, ge=0)\n')
write('app/schemas/dataset.py', 'from __future__ import annotations\n\nfrom datetime import date, datetime\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom app.schemas.common import APIModel\n\n\nclass DatasetRead(APIModel):\n    id: str\n    name: str\n    source_type: str\n    station_code: str | None\n    file_uri: str\n    checksum_sha256: str\n    row_count: int\n    schema_version: str\n    date_start: date | None\n    date_end: date | None\n    quality_report: dict[str, Any]\n    created_at: datetime\n\n\nclass OpenMeteoDatasetRequest(APIModel):\n    name: str\n    station_code: str\n    start_date: date\n    end_date: date\n    market_type: str = "daily_high_temperature"\n    assumed_lead_hours: int = Field(default=24, ge=1, le=240)\n')
write('app/schemas/model.py', 'from __future__ import annotations\n\nfrom datetime import date, datetime\nfrom typing import Any\n\nfrom app.schemas.common import APIModel\n\n\nclass ModelVersionRead(APIModel):\n    id: str\n    model_name: str\n    version: str\n    status: str\n    artifact_uri: str\n    artifact_sha256: str\n    feature_schema_version: str\n    training_dataset_id: str | None\n    training_start_date: date | None\n    training_end_date: date | None\n    metrics: dict[str, Any]\n    hyperparameters: dict[str, Any]\n    metadata: dict[str, Any]\n    promoted_at: datetime | None\n    retired_at: datetime | None\n    created_at: datetime\n\n\nclass ModelHealthResponse(APIModel):\n    service_status: str\n    model_status: str\n    model_version: str | None\n    model_id: str | None\n    feature_schema_version: str | None\n    artifact_verified: bool\n    supported_stations: list[str]\n    supported_market_types: list[str]\n    metrics: dict[str, Any]\n    warnings: list[str]\n    timestamp: datetime\n\n\nclass ModelPromotionRequest(APIModel):\n    model_version: str\n    reason: str\n\n\nclass ModelRollbackRequest(APIModel):\n    model_version: str\n    reason: str\n')
write('app/schemas/outcome.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom app.schemas.common import APIModel\n\n\nclass OutcomeCreate(APIModel):\n    market_id: str\n    station_code: str\n    official_value: float\n    official_source: str\n    settled_at: datetime\n    metadata: dict[str, Any] = Field(default_factory=dict)\n\n\nclass OutcomeRead(APIModel):\n    id: str\n    market_id: str\n    station_code: str\n    official_value: float\n    official_source: str\n    settled_at: datetime\n    metadata: dict[str, Any]\n    created_at: datetime\n    evaluations_created: int = 0\n')
write('app/schemas/prediction.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import Field, model_validator\n\nfrom app.schemas.common import APIModel\n\n\nclass OutcomeBracket(APIModel):\n    label: str\n    lower_bound: float | None = None\n    upper_bound: float | None = None\n\n    @model_validator(mode="after")\n    def ensure_some_bound(self) -> OutcomeBracket:\n        if self.lower_bound is None and self.upper_bound is None:\n            raise ValueError("At least one bracket bound is required.")\n        if (\n            self.lower_bound is not None\n            and self.upper_bound is not None\n            and self.lower_bound >= self.upper_bound\n        ):\n            raise ValueError("lower_bound must be less than upper_bound.")\n        return self\n\n\nclass PredictionRequest(APIModel):\n    market_id: str\n    market_ticker: str\n    station_code: str\n    market_type: str\n    target_time: datetime\n    lower_bound: float | None = None\n    upper_bound: float | None = None\n    unit: str = "F"\n    prediction_time: datetime | None = None\n    weather_observations: list[dict[str, Any]] = Field(default_factory=list)\n    weather_forecasts: list[dict[str, Any]] = Field(default_factory=list)\n    market_snapshot: dict[str, Any] = Field(default_factory=dict)\n    order_book: dict[str, Any] = Field(default_factory=dict)\n    feature_overrides: dict[str, Any] = Field(default_factory=dict)\n    brackets: list[OutcomeBracket] = Field(default_factory=list)\n    requested_model_version: str = "champion"\n\n    @model_validator(mode="after")\n    def validate_bounds(self) -> PredictionRequest:\n        if (\n            self.lower_bound is not None\n            and self.upper_bound is not None\n            and self.lower_bound >= self.upper_bound\n        ):\n            raise ValueError("lower_bound must be less than upper_bound.")\n        return self\n\n\nclass Driver(APIModel):\n    feature: str\n    contribution: float\n    current_value: Any\n    reference_value: Any\n    direction: str\n\n\nclass BracketProbability(APIModel):\n    label: str\n    lower_bound: float | None\n    upper_bound: float | None\n    raw_probability: float\n    calibrated_probability: float\n\n\nclass PredictionResponse(APIModel):\n    prediction_id: str\n    model_version: str\n    model_status: str\n    predicted_value: float\n    raw_probability: float | None\n    calibrated_probability: float | None\n    probability_lower_bound: float | None\n    probability_upper_bound: float | None\n    prediction_distribution: dict[str, Any]\n    bracket_probabilities: list[BracketProbability]\n    data_quality_score: float\n    data_freshness_seconds: int | None\n    feature_schema_version: str\n    top_positive_drivers: list[Driver]\n    top_negative_drivers: list[Driver]\n    historical_analogues: list[dict[str, Any]]\n    warnings: list[str]\n    trading_eligible: bool\n\n\nclass ExplanationResponse(APIModel):\n    model_version: str\n    predicted_value: float\n    top_positive_drivers: list[Driver]\n    top_negative_drivers: list[Driver]\n    model_disagreement: float | None\n    station_bias: float | None\n    historical_analogues: list[dict[str, Any]]\n    warnings: list[str]\n')
write('app/schemas/station.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom app.schemas.common import APIModel\n\n\nclass StationCreate(APIModel):\n    station_code: str = Field(min_length=2, max_length=32)\n    station_name: str = Field(min_length=2, max_length=255)\n    latitude: float = Field(ge=-90, le=90)\n    longitude: float = Field(ge=-180, le=180)\n    elevation_m: float | None = None\n    timezone: str = "UTC"\n    official_source: str | None = None\n    metadata: dict[str, Any] = Field(default_factory=dict)\n    active: bool = True\n\n\nclass StationRead(StationCreate):\n    id: str\n    created_at: datetime\n    updated_at: datetime\n')
write('app/schemas/training.py', 'from __future__ import annotations\n\nfrom datetime import datetime\nfrom typing import Any\n\nfrom pydantic import Field\n\nfrom app.schemas.common import APIModel\n\n\nclass TrainCandidateRequest(APIModel):\n    dataset_id: str\n    model_name: str = "weather-bracket-model"\n    requested_version: str | None = None\n    random_state: int = 42\n    max_iter: int = Field(default=300, ge=50, le=2000)\n    learning_rate: float = Field(default=0.05, gt=0, le=1)\n    max_leaf_nodes: int = Field(default=31, ge=4, le=255)\n    min_samples_leaf: int = Field(default=20, ge=2, le=1000)\n    l2_regularization: float = Field(default=0.1, ge=0, le=100)\n    calibration_method: str = Field(default="isotonic", pattern="^(isotonic|identity)$")\n\n\nclass TrainingJobRead(APIModel):\n    id: str\n    status: str\n    dataset_id: str\n    model_name: str\n    requested_version: str | None\n    configuration: dict[str, Any]\n    result_model_version_id: str | None\n    progress: float\n    logs: list[dict[str, Any]]\n    error_message: str | None\n    started_at: datetime | None\n    completed_at: datetime | None\n    created_at: datetime\n\n\nclass ModelComparisonRequest(APIModel):\n    champion_version: str\n    challenger_version: str\n    dataset_id: str\n    minimum_brier_improvement: float = 0.0\n    maximum_mae_degradation: float = 0.0\n\n\nclass ModelComparisonResponse(APIModel):\n    champion_version: str\n    challenger_version: str\n    dataset_id: str\n    champion_metrics: dict[str, Any]\n    challenger_metrics: dict[str, Any]\n    metric_deltas: dict[str, float]\n    recommendation: str\n    reasons: list[str]\n')
