write('app/services/audit_service.py', 'from __future__ import annotations\n\nfrom typing import Any\n\nfrom sqlalchemy.orm import Session\n\nfrom app.db.models import AuditEvent\n\n\ndef record_audit(\n    db: Session,\n    *,\n    actor_fingerprint: str,\n    action: str,\n    entity_type: str,\n    entity_id: str | None = None,\n    details: dict[str, Any] | None = None,\n) -> AuditEvent:\n    event = AuditEvent(\n        actor_fingerprint=actor_fingerprint,\n        action=action,\n        entity_type=entity_type,\n        entity_id=entity_id,\n        details=details or {},\n    )\n    db.add(event)\n    db.commit()\n    db.refresh(event)\n    return event\n')
